            RequestCommand:InvokeServer(";Music "..music.ID)
            wait(0)
            RequestCommand:InvokeServer(";Pitch "..music.Pitch)
            wait(0)
            RequestCommand:InvokeServer(";volume inf")
        end)
    end
end

